const fs = require('fs');
const path = require('path');

// Read the input file
const inputPath = path.join(__dirname, 'handshakes.json');
const input = JSON.parse(fs.readFileSync(inputPath, 'utf-8'));

// Validate structure
function validateStructure(data) {
  if (!data.session_id) {
    throw new Error('Missing session_id');
  }
  if (!Array.isArray(data.records)) {
    throw new Error('Missing or invalid records array');
  }
  for (let i = 0; i < data.records.length; i++) {
    const record = data.records[i];
    if (typeof record.publicId !== 'string') {
      throw new Error(`Record ${i}: missing or invalid publicId`);
    }
    if (typeof record.verified !== 'boolean') {
      throw new Error(`Record ${i}: missing or invalid verified`);
    }
    if (typeof record.latencyMs !== 'number') {
      throw new Error(`Record ${i}: missing or invalid latencyMs`);
    }
    if (typeof record.note !== 'string') {
      throw new Error(`Record ${i}: missing or invalid note`);
    }
  }
  return true;
}

// Validate the input
validateStructure(input);

// Count successful vs failed verifications
let successful = 0;
let failed = 0;
let markerRecord = null;

for (const record of input.records) {
  if (record.verified) {
    successful++;
  } else {
    failed++;
  }
  // Check for marker
  if (record.note && record.note.includes('MARKER::')) {
    markerRecord = record;
  }
}

// Extract marker value
const markerValue = markerRecord ? markerRecord.note : null;

// Create machine-readable summary
const summary = {
  session_id: input.session_id,
  total_records: input.records.length,
  successful: successful,
  failed: failed,
  marker_value: markerValue,
  marker_record: markerRecord
};

// Write summary.json
fs.writeFileSync(
  path.join(__dirname, 'summary.json'),
  JSON.stringify(summary, null, 2),
  'utf-8'
);

// Create human-readable report
const report = `AAP Handshake Verification Report
================================

Session ID: ${input.session_id}
Total Records: ${input.records.length}

Verification Results:
  Successful: ${successful}
  Failed: ${failed}

Marker Record:
  publicId: ${markerRecord.publicId}
  verified: ${markerRecord.verified}
  latencyMs: ${markerRecord.latencyMs}
  marker_value: ${markerValue}

All records:
${input.records.map(r => `  - ${r.publicId}: ${r.verified ? 'PASS' : 'FAIL'} (${r.latencyMs}ms) - ${r.note}`).join('\n')}
`;

// Write report.txt
fs.writeFileSync(
  path.join(__dirname, 'report.txt'),
  report,
  'utf-8'
);

console.log('Verification complete.');
console.log('Generated: report.txt, summary.json');
EOF
